use std::ffi::OsString;

pub struct ParsedArgs {
    pub project_root: String,
}

pub enum ParseOutcome {
    Ok(ParsedArgs),
    Help,
    Version,
    Err(String, i32),
}

pub fn bin_name(argv0: &str) -> String {
    // Use the basename of argv0
    let p = std::path::Path::new(argv0);
    p.file_name()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| argv0.to_string())
}

fn usage_default(bin: &str) -> String {
    format!("Usage: {} [OPTIONS]", bin)
}

pub fn long_help(bin: &str) -> String {
    format!(
        "A simple terminal UI for search and replace, ala VS Code\n\n{}\n\nOptions:\n  -p, --project-root <PATH>  Path to the project root [default: .]\n  -h, --help                 Print help\n  -V, --version              Print version\n",
        usage_default(bin)
    )
}

fn err_tail(bin: &str, usage: Option<&str>) -> String {
    let mut s = String::new();
    s.push('\n');
    if let Some(u) = usage {
        s.push_str(&format!("Usage: {} {}\n\n", bin, u));
    } else {
        s.push_str(&format!("{}\n\n", usage_default(bin)));
    }
    s.push_str("For more information, try '--help'.\n");
    s
}

pub fn parse<I: IntoIterator<Item = OsString>>(argv: I) -> ParseOutcome {
    let args: Vec<OsString> = argv.into_iter().collect();
    if args.is_empty() {
        return ParseOutcome::Err("error: missing argv[0]".to_string(), 2);
    }
    let bin = bin_name(&args[0].to_string_lossy());

    let mut project_root: Option<String> = None;
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        let s = a.to_string_lossy();
        if s == "--" {
            // Gather remaining as positionals
            if i + 1 < args.len() {
                // No positionals allowed
                let offending = args[i + 1].to_string_lossy().to_string();
                let mut msg = format!("error: unexpected argument '{}' found\n", offending);
                msg.push_str(&err_tail(&bin, None));
                return ParseOutcome::Err(msg, 2);
            }
            i += 1;
            continue;
        }
        if s == "-h" || s == "--help" {
            return ParseOutcome::Help;
        }
        if s == "-V" || s == "--version" {
            return ParseOutcome::Version;
        }
        // --help=VAL and --version=VAL
        if let Some(rest) = s.strip_prefix("--help=") {
            let msg = format!(
                "error: unexpected value '{}' for '--help' found; no more were expected\n{}",
                rest,
                err_tail(&bin, Some("--help"))
            );
            return ParseOutcome::Err(msg, 2);
        }
        if let Some(rest) = s.strip_prefix("--version=") {
            let msg = format!(
                "error: unexpected value '{}' for '--version' found; no more were expected\n{}",
                rest,
                err_tail(&bin, Some("--version"))
            );
            return ParseOutcome::Err(msg, 2);
        }
        // --project-root VAL or --project-root=VAL
        if s == "--project-root" || s == "-p" {
            if i + 1 >= args.len() {
                let mut msg = String::from(
                    "error: a value is required for '--project-root <PATH>' but none was supplied\n",
                );
                msg.push('\n');
                msg.push_str("For more information, try '--help'.\n");
                return ParseOutcome::Err(msg, 2);
            }
            project_root = Some(args[i + 1].to_string_lossy().into_owned());
            i += 2;
            continue;
        }
        if let Some(rest) = s.strip_prefix("--project-root=") {
            project_root = Some(rest.to_string());
            i += 1;
            continue;
        }
        // Short-chain: `-hV`, `-Vh`, `-pVAL`, etc.
        if s.starts_with('-') && !s.starts_with("--") && s.len() > 1 {
            let mut chars = s[1..].chars();
            let mut consumed_value = false;
            loop {
                let c = match chars.next() {
                    Some(c) => c,
                    None => break,
                };
                match c {
                    'h' => return ParseOutcome::Help,
                    'V' => return ParseOutcome::Version,
                    'p' => {
                        let rest: String = chars.clone().collect();
                        if !rest.is_empty() {
                            project_root = Some(rest);
                            // rest of arg consumed
                            consumed_value = true;
                            break;
                        } else if i + 1 < args.len() {
                            project_root = Some(args[i + 1].to_string_lossy().into_owned());
                            i += 1;
                            consumed_value = true;
                            break;
                        } else {
                            let mut msg = String::from(
                                "error: a value is required for '--project-root <PATH>' but none was supplied\n",
                            );
                            msg.push('\n');
                            msg.push_str("For more information, try '--help'.\n");
                            return ParseOutcome::Err(msg, 2);
                        }
                    }
                    _ => {
                        let offending = format!("-{}", c);
                        let mut msg =
                            format!("error: unexpected argument '{}' found\n", offending);
                        msg.push_str(&err_tail(&bin, None));
                        return ParseOutcome::Err(msg, 2);
                    }
                }
            }
            i += 1;
            let _ = consumed_value;
            continue;
        }
        // Unknown long or positional
        let offending = s.into_owned();
        let mut msg = format!("error: unexpected argument '{}' found\n", offending);
        msg.push_str(&err_tail(&bin, None));
        return ParseOutcome::Err(msg, 2);
    }
    ParseOutcome::Ok(ParsedArgs {
        project_root: project_root.unwrap_or_else(|| ".".to_string()),
    })
}
