//! Raw termios handling using libc FFI.
use std::io::{self, Write};
use std::os::unix::io::RawFd;

#[repr(C)]
#[derive(Copy, Clone)]
pub struct Termios {
    pub c_iflag: u32,
    pub c_oflag: u32,
    pub c_cflag: u32,
    pub c_lflag: u32,
    pub c_line: u8,
    pub c_cc: [u8; 32],
    pub c_ispeed: u32,
    pub c_ospeed: u32,
}

#[repr(C)]
#[derive(Copy, Clone, Default)]
pub struct Winsize {
    pub ws_row: u16,
    pub ws_col: u16,
    pub ws_xpixel: u16,
    pub ws_ypixel: u16,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct PollFd {
    pub fd: i32,
    pub events: i16,
    pub revents: i16,
}

pub const POLLIN: i16 = 0x0001;

extern "C" {
    pub fn tcgetattr(fd: RawFd, termios_p: *mut Termios) -> i32;
    pub fn tcsetattr(fd: RawFd, optional_actions: i32, termios_p: *const Termios) -> i32;
    pub fn ioctl(fd: RawFd, request: u64, ...) -> i32;
    pub fn read(fd: RawFd, buf: *mut u8, count: usize) -> isize;
    pub fn poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32;
    pub fn __errno_location() -> *mut i32;
    pub fn strerror(errnum: i32) -> *const u8;
}

pub const TCSANOW: i32 = 0;
pub const TIOCGWINSZ: u64 = 0x5413;

pub const ICANON: u32 = 0x2;
pub const ECHO: u32 = 0x8;
pub const ISIG: u32 = 0x1;
pub const IEXTEN: u32 = 0x8000;
pub const IXON: u32 = 0x400;
pub const ICRNL: u32 = 0x100;
pub const BRKINT: u32 = 0x2;
pub const INPCK: u32 = 0x10;
pub const ISTRIP: u32 = 0x20;
pub const OPOST: u32 = 0x1;
pub const VMIN: usize = 6;
pub const VTIME: usize = 5;

pub fn errno() -> i32 {
    unsafe { *__errno_location() }
}

pub fn errno_str() -> String {
    let e = errno();
    let p = unsafe { strerror(e) };
    if p.is_null() {
        return format!("os error {}", e);
    }
    let mut len = 0usize;
    unsafe {
        while *p.add(len) != 0 {
            len += 1;
        }
    }
    let slice = unsafe { std::slice::from_raw_parts(p, len) };
    let msg = std::str::from_utf8(slice).unwrap_or("");
    format!("{} (os error {})", msg, e)
}

pub struct RawMode {
    fd: RawFd,
    original: Termios,
}

pub fn try_get_attrs(fd: RawFd) -> io::Result<Termios> {
    let mut t: Termios = unsafe { std::mem::zeroed() };
    let rc = unsafe { tcgetattr(fd, &mut t as *mut _) };
    if rc != 0 {
        return Err(io::Error::from_raw_os_error(errno()));
    }
    Ok(t)
}

impl RawMode {
    pub fn enable(fd: RawFd) -> io::Result<Self> {
        let original = try_get_attrs(fd)?;
        let mut t = original;
        t.c_iflag &= !(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
        t.c_oflag &= !OPOST;
        t.c_lflag &= !(ECHO | ICANON | ISIG | IEXTEN);
        t.c_cc[VMIN] = 0;
        t.c_cc[VTIME] = 0;
        let rc = unsafe { tcsetattr(fd, TCSANOW, &t as *const _) };
        if rc != 0 {
            return Err(io::Error::from_raw_os_error(errno()));
        }
        Ok(RawMode { fd, original })
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        unsafe {
            tcsetattr(self.fd, TCSANOW, &self.original as *const _);
        }
    }
}

pub fn winsize(fd: RawFd) -> Winsize {
    let mut ws: Winsize = Winsize::default();
    let _ = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut _) };
    if ws.ws_row == 0 {
        ws.ws_row = 24;
    }
    if ws.ws_col == 0 {
        ws.ws_col = 80;
    }
    ws
}

pub fn write_all(s: &str) -> io::Result<()> {
    let mut out = io::stdout();
    out.write_all(s.as_bytes())?;
    out.flush()
}

pub fn poll_in(fd: RawFd, timeout_ms: i32) -> i32 {
    let mut pfd = PollFd {
        fd,
        events: POLLIN,
        revents: 0,
    };
    unsafe { poll(&mut pfd as *mut _, 1, timeout_ms) }
}

pub fn read_byte(fd: RawFd) -> Option<u8> {
    let mut buf = [0u8; 1];
    let rc = unsafe { read(fd, buf.as_mut_ptr(), 1) };
    if rc <= 0 {
        None
    } else {
        Some(buf[0])
    }
}
