pub const IXON: u32 = 0x400;
pub const ICRNL: u32 = 0x100;
pub const BRKINT: u32 = 0x2;
pub const INPCK: u32 = 0x10;
pub const ISTRIP: u32 = 0x20;
pub const OPOST: u32 = 0x1;
pub const VMIN: usize = 6;
pub const VTIME: usize = 5;

