const ALT_SCREEN_ON: &str = "\x1b[?1049h\x1b[?25l";
const ALT_SCREEN_OFF: &str = "\x1b[?1049l\x1b[?25h";

fn move_to(row: u16, col: u16) -> String {
    format!("\x1b[{};{}H", row, col)
}

pub fn run(project_root: &Path) -> io::Result<()> {
    // Open /dev/tty to interact with the terminal regardless of stdin/stdout redirection.
    let tty = File::options().read(true).write(true).open("/dev/tty")?;
    let fd = tty.as_raw_fd();

    // Attempt to enter raw mode; this can fail if /dev/tty isn't a terminal.
    let _attrs = term::try_get_attrs(fd)?;
    let raw = term::RawMode::enable(fd)?;

    let mut out = io::stdout();
    write!(out, "{}", ALT_SCREEN_ON)?;
    out.flush()?;

    let mut app = App {
        project_root: project_root.to_path_buf(),
        search_text: String::new(),
        replace_text: String::new(),
        search_mode: SearchMode::Simple,
        replace_mode: ReplaceMode::Simple,
        focus: Pane::Search,
        hits: Vec::new(),
        selected: 0,
        show_help: false,
        help_tab: 1,
        running: true,
        tty_fd: fd,
        raw,
        tty_file: tty,
    };

    let result = app.main_loop();

    let mut out = io::stdout();
    let _ = write!(out, "{}", ALT_SCREEN_OFF);
    let _ = out.flush();

    result
}

impl App {
    fn main_loop(&mut self) -> io::Result<()> {
        while self.running {
            self.draw()?;
            self.handle_input()?;
