        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
    fn next(self) -> Self {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Pane {
    Search,
    Replace,
    Results,
}

impl Pane {
    fn next(self) -> Self {
        match self {
            Pane::Search => Pane::Replace,
            Pane::Replace => Pane::Results,
            Pane::Results => Pane::Search,
        }
    }
    fn prev(self) -> Self {
        match self {
            Pane::Search => Pane::Results,
            Pane::Replace => Pane::Search,
            Pane::Results => Pane::Replace,
        }
    }
}

struct SearchHit {
