        bot.push('╯');
        out.push_str(&move_to(row + h - 1, col));
        out.push_str(color);
        out.push_str(&bot);
        out.push_str(reset);
    }

    fn draw_preview(&self, out: &mut String, col: u16, row_off: u16, w: usize, h: usize) {
        let hit = match self.hits.get(self.selected) {
            Some(h) => h,
            None => return,
        };
        let content = match fs::read_to_string(&hit.file) {
            Ok(s) => s,
            Err(_) => return,
        };
        let match_lines: std::collections::HashSet<usize> =
            hit.lines.iter().map(|(n, _)| *n).collect();
        let all_lines: Vec<&str> = content.lines().collect();
        // Find first match and show around it.
        let first = hit.lines.first().map(|(n, _)| *n).unwrap_or(1);
        let start = first.saturating_sub(1);
        let end = (start + h).min(all_lines.len());
        let mut r = 0u16;
        let mut prev_match = false;
        for idx in start..end {
            let line_no = idx + 1;
            let is_match = match_lines.contains(&line_no);
            let numbered = format!("{:>4} {}", line_no, all_lines[idx]);
            out.push_str(&move_to(r + row_off, col));
            let clipped = clip_text(&numbered, w);
            if is_match {
                out.push_str(&format!("\x1b[33m{}\x1b[0m", clipped));
            } else {
                out.push_str(&clipped);
            }
            r += 1;
            if is_match && idx + 1 < end {
                // Draw separator below like the original
                out.push_str(&move_to(r + row_off, col));
                let sep: String = "-".repeat(w);
                out.push_str(&sep);
                r += 1;
                prev_match = true;
            } else {
                prev_match = false;
            }
            if r as usize >= h {
                break;
            }
        }
        let _ = prev_match;
    }

    fn draw_help(&self, out: &mut String, cols: u16, rows: u16) {
        let w: u16 = 80.min(cols.saturating_sub(4));
        let h: u16 = 18.min(rows.saturating_sub(4));
        let row = (rows.saturating_sub(h)) / 2;
        let col = (cols.saturating_sub(w)) / 2;
        let mut title = String::from(" [1] Global ─ [2] Navigation ");
        let right = "Press 'q' to close";
        let fill = (w as usize).saturating_sub(title.chars().count() + right.chars().count() + 2);
        for _ in 0..fill {
            title.push('─');
        }
        title.push_str(right);

        // Clear dialog area
        for r in 0..h {
            out.push_str(&move_to(row + r, col));
            out.push_str(&" ".repeat(w as usize));
        }
        self.draw_box(out, row, col, w, h, "", "", true);
        // Overlay title
        out.push_str(&move_to(row, col + 1));
        out.push_str(&clip_text(&title, w as usize - 2));
        // Content
        let lines: Vec<&str> = if self.help_tab == 1 {
            vec![
                "",
                " - Ctrl-c: Quit",
                " - Ctrl-d: Quit",
                " - Ctrl-b: Help dialog",
                " - Ctrl-o: Process Replace For All Files",
                " - Ctrl-n: Loop through search and replace modes",
                " - Enter: Select/Deselect file",
                " - d: delete file/delete line from the replace process",
                " - r: Replace Selected File Or Line",
            ]
        } else {
            vec![
                "",
                " - Tab: Loop through panes",
                " - j/UpArrow: Move up",
                " - k/DownArrow: Move down",
                " - h/g/LeftArrow: Move to Top",
                " - l/G/RightArrow: Move to Bottom",
            ]
        };
        for (i, line) in lines.iter().enumerate() {
            let r = row + 1 + i as u16;
            if r >= row + h - 1 {
                break;
            }
            out.push_str(&move_to(r, col + 1));
            out.push_str(&clip_text(line, w as usize - 2));
        }
    }

    fn handle_input(&mut self) -> io::Result<()> {
        let rc = term::poll_in(self.tty_fd, 200);
        if rc <= 0 {
            return Ok(());
        }
        let b = match term::read_byte(self.tty_fd) {
            Some(b) => b,
            None => return Ok(()),
        };
        if self.show_help {
            return self.handle_help_input(b);
        }
        match b {
            0x03 | 0x04 => self.running = false,             // Ctrl-c, Ctrl-d
            0x02 => self.show_help = true,                    // Ctrl-b
            0x0e => {                                         // Ctrl-n
                match self.focus {
                    Pane::Search => self.search_mode = self.search_mode.next(),
                    Pane::Replace => self.replace_mode = self.replace_mode.next(),
                    _ => {}
                }
            }
            0x09 => self.focus = self.focus.next(),           // Tab
            0x0f => {                                         // Ctrl-o
                self.process_replace_all();
            }
            0x0d => {                                         // Enter
                if self.focus == Pane::Search {
                    self.run_search();
                }
            }
            0x1b => {                                         // Escape / Escape sequence
                let seq = self.read_escape();
                self.handle_escape(&seq);
            }
            0x7f => {
                // Backspace
                match self.focus {
                    Pane::Search => {
                        self.search_text.pop();
                        self.run_search();
                    }
                    Pane::Replace => {
                        self.replace_text.pop();
                    }
                    _ => {}
                }
            }
            b'j' if self.focus == Pane::Results => self.move_sel(1),
            b'k' if self.focus == Pane::Results => self.move_sel(-1),
            b'g' | b'h' if self.focus == Pane::Results => {
                self.selected = 0;
            }
            b'G' | b'l' if self.focus == Pane::Results => {
                if !self.hits.is_empty() {
                    self.selected = self.hits.len() - 1;
                }
            }
            b'r' if self.focus == Pane::Results => {
                self.replace_selected();
            }
            b'd' if self.focus == Pane::Results => {
                if self.selected < self.hits.len() {
                    self.hits.remove(self.selected);
                    if self.selected >= self.hits.len() && self.selected > 0 {
                        self.selected -= 1;
                    }
                }
            }
            _ => {
                if b >= 0x20 && b < 0x7f {
                    match self.focus {
                        Pane::Search => {
                            self.search_text.push(b as char);
                            self.run_search();
                        }
                        Pane::Replace => {
                            self.replace_text.push(b as char);
                        }
                        _ => {}
                    }
                }
            }
        }
        Ok(())
    }

    fn handle_help_input(&mut self, b: u8) -> io::Result<()> {
        match b {
            0x03 | 0x04 => self.running = false,
            b'q' => self.show_help = false,
            0x1b => {
                let seq = self.read_escape();
                if seq.is_empty() {
                    self.show_help = false;
                } else {
                    self.handle_escape(&seq);
                }
            }
            _ => {}
        }
        Ok(())
    }

    fn read_escape(&self) -> Vec<u8> {
        let mut buf = Vec::new();
        // Wait briefly for additional bytes
        let rc = term::poll_in(self.tty_fd, 30);
        if rc <= 0 {
            return buf;
        }
        while let Some(b) = term::read_byte(self.tty_fd) {
            buf.push(b);
            if buf.len() > 6 {
                break;
            }
            let rc = term::poll_in(self.tty_fd, 10);
            if rc <= 0 {
                break;
            }
        }
        buf
    }

    fn handle_escape(&mut self, seq: &[u8]) {
        if self.show_help {
            // Left/Right to change tab
            if seq == b"[C" {
                self.help_tab = if self.help_tab == 1 { 2 } else { 1 };
            } else if seq == b"[D" {
                self.help_tab = if self.help_tab == 1 { 2 } else { 1 };
            }
        } else {
            if seq == b"[Z" {
                // Shift-Tab (Backtab)
                self.focus = self.focus.prev();
            } else if seq == b"[A" {
                self.move_sel(-1);
            } else if seq == b"[B" {
                self.move_sel(1);
            }
        }
    }

    fn move_sel(&mut self, d: i32) {
        let n = self.hits.len() as i32;
        if n == 0 {
            return;
        }
        let mut s = self.selected as i32 + d;
        if s < 0 {
            s = 0;
        }
        if s >= n {
            s = n - 1;
        }
        self.selected = s as usize;
    }

    fn run_search(&mut self) {
        self.hits.clear();
        self.selected = 0;
        if self.search_text.is_empty() {
            return;
        }
        let needle = self.search_text.clone();
        let mode = self.search_mode;
        let root = self.project_root.clone();
        search_dir(&root, &root, &needle, mode, &mut self.hits);
        // Stable ordering
        self.hits.sort_by(|a, b| a.rel.cmp(&b.rel));
    }

    fn replace_selected(&mut self) {
        if self.search_text.is_empty() {
            return;
        }
        let mode = self.replace_mode;
        let find = self.search_text.clone();
        let rep = self.replace_text.clone();
        if let Some(hit) = self.hits.get(self.selected).cloned_hit() {
            let _ = replace_in_file(&hit.file, &find, &rep, self.search_mode, mode);
            // Re-run search to refresh list
            self.run_search();
        }
    }

    fn process_replace_all(&mut self) {
        if self.search_text.is_empty() {
            return;
        }
        let mode = self.replace_mode;
        let find = self.search_text.clone();
        let rep = self.replace_text.clone();
        let files: Vec<PathBuf> = self.hits.iter().map(|h| h.file.clone()).collect();
        for f in files {
            let _ = replace_in_file(&f, &find, &rep, self.search_mode, mode);
        }
        self.run_search();
    }
}

trait CloneHit {
    fn cloned_hit(self) -> Option<SearchHit>;
}

impl CloneHit for Option<&SearchHit> {
    fn cloned_hit(self) -> Option<SearchHit> {
        self.map(|h| SearchHit {
            file: h.file.clone(),
            rel: h.rel.clone(),
            lines: h.lines.clone(),
        })
    }
}

impl Clone for SearchHit {
    fn clone(&self) -> SearchHit {
        SearchHit {
            file: self.file.clone(),
            rel: self.rel.clone(),
            lines: self.lines.clone(),
        }
    }
}

fn search_dir(
    root: &Path,
    dir: &Path,
    needle: &str,
    mode: SearchMode,
    out: &mut Vec<SearchHit>,
) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for ent in entries.flatten() {
        let path = ent.path();
        let name = ent.file_name();
        let name_s = name.to_string_lossy();
        if name_s.starts_with('.') {
            continue;
        }
        let ft = match ent.file_type() {
            Ok(f) => f,
            Err(_) => continue,
        };
        if ft.is_dir() {
            search_dir(root, &path, needle, mode, out);
        } else if ft.is_file() {
            if let Ok(contents) = fs::read_to_string(&path) {
                let mut lines = Vec::new();
                for (i, line) in contents.lines().enumerate() {
                    if match_line(line, needle, mode) {
                        lines.push((i + 1, line.to_string()));
                    }
                }
                if !lines.is_empty() {
                    let rel = path
                        .strip_prefix(root)
                        .unwrap_or(&path)
                        .display()
                        .to_string();
                    out.push(SearchHit {
                        file: path,
                        rel,
                        lines,
                    });
                }
            }
        }
    }
}

fn match_line(line: &str, needle: &str, mode: SearchMode) -> bool {
    match mode {
        SearchMode::Simple => line.to_lowercase().contains(&needle.to_lowercase()),
        SearchMode::MatchCase => line.contains(needle),
        SearchMode::MatchWholeWord => word_contains(line, needle, false),
        SearchMode::MatchCaseWholeWord => word_contains(line, needle, true),
        SearchMode::Regex => line.contains(needle),
    }
}

fn word_contains(hay: &str, needle: &str, case_sensitive: bool) -> bool {
    if needle.is_empty() {
        return false;
    }
    let hay_c = if case_sensitive {
        hay.to_string()
    } else {
        hay.to_lowercase()
    };
    let needle_c = if case_sensitive {
        needle.to_string()
    } else {
        needle.to_lowercase()
    };
    let hb = hay_c.as_bytes();
    let nb = needle_c.as_bytes();
    let mut i = 0;
    while i + nb.len() <= hb.len() {
        if &hb[i..i + nb.len()] == nb {
            let before_ok = i == 0 || !is_word(hb[i - 1]);
            let after_ok = i + nb.len() == hb.len() || !is_word(hb[i + nb.len()]);
            if before_ok && after_ok {
                return true;
            }
        }
        i += 1;
    }
    false
}

fn is_word(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn replace_in_file(
    path: &Path,
    find: &str,
    rep: &str,
    smode: SearchMode,
    rmode: ReplaceMode,
) -> io::Result<()> {
    let contents = fs::read_to_string(path)?;
    let mut out = String::with_capacity(contents.len());
    for line in contents.lines() {
        if match_line(line, find, smode) {
            match rmode {
                ReplaceMode::DeleteLine => continue,
                ReplaceMode::PreserveCase | ReplaceMode::Simple => {
                    let replaced = if smode == SearchMode::Simple {
                        replace_insensitive(line, find, rep)
                    } else {
                        line.replace(find, rep)
                    };
                    out.push_str(&replaced);
                    out.push('\n');
                }
            }
        } else {
            out.push_str(line);
            out.push('\n');
        }
    }
    // Preserve trailing newline behaviour roughly
    if !contents.ends_with('\n') && out.ends_with('\n') {
        out.pop();
    }
    let mut f = File::create(path)?;
    f.write_all(out.as_bytes())?;
    Ok(())
}

fn replace_insensitive(hay: &str, needle: &str, rep: &str) -> String {
    if needle.is_empty() {
        return hay.to_string();
    }
    let hay_l = hay.to_lowercase();
    let needle_l = needle.to_lowercase();
    let mut out = String::new();
    let mut i = 0;
    let hb = hay.as_bytes();
    let hlb = hay_l.as_bytes();
    let nlb = needle_l.as_bytes();
    while i < hb.len() {
        if i + nlb.len() <= hlb.len() && &hlb[i..i + nlb.len()] == nlb {
            out.push_str(rep);
            i += nlb.len();
        } else {
            out.push(hb[i] as char);
            i += 1;
        }
    }
    out
}

fn clip_text(s: &str, w: usize) -> String {
    let mut out = String::new();
    let mut count = 0;
    for c in s.chars() {
        if count >= w {
            break;
        }
        out.push(c);
        count += 1;
    }
    out
}

