// Add a helper trait for io::Error message formatting that matches Linux strerror output
trait IoErrKindMessage {
    fn kind_message(&self) -> String;
}

impl IoErrKindMessage for std::io::Error {
    fn kind_message(&self) -> String {
        match self.raw_os_error() {
            Some(code) => {
                let p = unsafe { term::strerror(code) };
                if p.is_null() {
                    return format!("os error {}", code);
                }
                let mut len = 0usize;
                unsafe {
                    while *p.add(len) != 0 {
                        len += 1;
                    }
                }
                let slice = unsafe { std::slice::from_raw_parts(p, len) };
                std::str::from_utf8(slice).unwrap_or("").to_string()
            }
            None => self.to_string(),
        }
    }
}
